import React from 'react';

import Name from '../../partials/name';
import Paragraph from '../../partials/paragraph';

const requestTokenType =
`interface RequestToken {
	_id: string;
}`;

const ConceptClientPage : React.FC<{className? : string}> = ({ className }) => (
    <article className={ `concept-request-token-page ${ className }` }>
        <h1>Request Token</h1>
        <BodyCurrent />
    </article>
);

export default ConceptClientPage;

function BodyCurrent() {
    return (
        <div>
			<code><pre>{ requestTokenType }</pre></code>
            <h3>What is a request token?</h3>
			<Paragraph>
				A request token is an object normally assigned to an incoming server request. All <Name /> instances created at the servicing of the request are identified by this token. It is a requirement in the server. While this token may be assigned to a runnining application while in the browser, it is unnecessary.
			</Paragraph>
			<h4>Characteristics.</h4>
			<Paragraph>
				A request token is any arbitrary object of the <code>RequestToken</code> type whose <code>_id</code> property is unique in the applictation at any given time. 
			</Paragraph>
			<Paragraph>
				A instant request token is recognized both by its reference and by its <code>_id</code> property. An identical object is not recognized as the instant token.
			</Paragraph>
			<Paragraph>
				Any attempt to obtain a <Name /> instance using a request token whose <code>_id</code> has been altered will result in error.
			</Paragraph>
        </div>
    );
}
